settleUserPathMatches: ({ queryKey: qkIn, matches }) => {
  const pending = get().pendingPathMatch
  const queryKey = qkIn?.trim() || pending?.queryKey || ''
  if (!queryKey) {
    return { pathKeys: [], ok: false, note: '无 queryKey / 无挂起匹配' }
  }
  if (matches.length === 0) {
    return { pathKeys: [], ok: false, note: '用户确认为空' }
  }

  // 优先：挂起里台已绑定的同窝对；无挂起则现场再绑一次
  let allow = new Set(
    (pending?.boundPairs ?? []).map(
      (p) => `${p.inferKey}::${p.prospectKey}`,
    ),
  )
  if (allow.size === 0) {
    const docId = useIndexGate.getState().bookIndex?.docId?.trim() ?? ''
    if (docId) {
      const family = new Set(get().listQuerySelfAndAncestors(queryKey))
      const bound = bindInferProspectByBookLineage({
        docId,
        inferEdges: get().inferEdges.filter((e) => e.queryKey === queryKey),
        prospects: get().prospects.filter((p) => family.has(p.queryKey)),
        deskDeliveries: get().deskDeliveries,
      })
      allow = new Set(
        bound.map((b) => `${b.inferKey}::${b.prospectKey}`),
      )
    }
  }
  if (allow.size === 0) {
    return {
      pathKeys: [],
      ok: false,
      note: '无同窝绑定对可确认（台未圈出 book 血缘）',
    }
  }

  const clean = matches.filter((m) =>
    allow.has(`${m.inferKey.trim()}::${m.prospectKey.trim()}`),
  )
  const dropped = matches.length - clean.length
  if (clean.length === 0) {
    return {
      pathKeys: [],
      ok: false,
      note:
        dropped > 0
          ? `确认对均不在同窝绑定集（已丢×${dropped}）`
          : '确认键不在同窝集',
    }
  }

  const settled = get().settlePaths({
    queryKey,
    llmCallId: newLlmCallId('path'),
    matches: clean.map((m) => ({
      inferKey: m.inferKey.trim(),
      prospectKey: m.prospectKey.trim(),
      matchMode: 'user' as const,
    })),
  })
  set({ pendingPathMatch: null })
  return {
    pathKeys: settled.pathKeys,
    ok: settled.pathKeys.length > 0,
    note:
      `用户确认 path×${settled.pathKeys.length}` +
      (dropped ? ` · 非同窝丢×${dropped}` : ''),
  }
},

