      const row = r as Record<string, unknown>
      push(
        String(row.inferKey ?? ''),
        String(row.prospectKey ?? ''),
        String(row.status ?? ''),
      )
    }
  }

  // JSON 整段失败或数组被截断：正则捞完整行
  if (out.length === 0) {
