/**
 * 复用闸：主坐标 = normKey + 展开(归一化推理正文)；能则现 qk ──reuse──► normKey。
 */
export async function runReuseGate(input: {
  qNow: string
  /** 用于 brief↔book 精细剔除 */
  docId?: string
  /** @deprecated 架构以 neighbour→path 为准；保留兼容 */
