  const reuseCallId = newLlmCallId('reuse')
  const adoptedRows: Array<{
    reuseKey: string
    pathKey: string
  }> = []
  for (const j of judgments) {
    if (!j.canSolve) continue
    const winPath =
      byPath.get(j.pathKey) ||
      paths.find((p) => p.inferKey === j.inferKey)
    if (!winPath) continue
    const adopted = useAttentionIo.getState().adoptReusePath({
      question: input.qNow,
      pathKey: winPath.pathKey,
