    }
  }

  const reuseCallId = newLlmCallId('reuse')
  const adoptedRows: Array<{
    queryKey: string
    reuseKey: string
    pathKey: string
    normKey: string
    oldQueryKey: string
    inferKeys: string[]
    prospectKeys: string[]
  }> = []
