 */
export async function skipPendingPathMatchToSupervise(input?: {
  onProgress?: (msg: string) => void
}): Promise<{ pathKeys: string[]; note: string; raw: string }> {
  const st = useAttentionIo.getState()
  const pending = st.pendingPathMatch
  if (!pending) {
    const anyUser = st.paths.filter((p) => p.matchMode === 'user')
    if (anyUser.length > 0) {
      return {
        pathKeys: anyUser.map((p) => p.pathKey),
        note: '无挂起 · 已有用户 path',
        raw: '',
      }
    }
    return { pathKeys: [], note: '无挂起的 path 可跳过', raw: '' }
  }
  const qk = pending.queryKey
  const preBound = pending.boundPairs
  st.clearPendingPathMatch()
  return runPathMatchSuperviseIfNeeded({
    queryKey: qk,
    onProgress: input?.onProgress,
    force: true,
    preBoundPairs: preBound,
  })
}

/**
 * 台血缘绑定 + 信效度评测（非配对 LLM）。
 * 仅当本轮尚无用户 path、且（force 或已无 pending）时才跑。
 */
export async function runPathMatchSuperviseIfNeeded(input: {
  queryKey: string
  onProgress?: (msg: string) => void
  /** true = 用户已显式跳过手工确认 */
  force?: boolean
  /** 跳过前挂起里已绑定的对（避免 clear 后丢） */
  preBoundPairs?: Array<{
    inferKey: string
    prospectKey: string
    briefKey: string
    sharedBookKeys: string[]
  }>
}): Promise<{ pathKeys: string[]; note: string; raw: string }> {
  const st = useAttentionIo.getState()
  const qk = input.queryKey.trim()
  const existingUser = st
    .listPathsForQueryKey(qk)
    .filter((p) => p.matchMode === 'user')
  if (existingUser.length > 0) {
    return {
      pathKeys: existingUser.map((p) => p.pathKey),
      note: `用户已确认 path×${existingUser.length} · 不触发信效度 LLM`,
      raw: '',
    }
  }
  if (st.pendingPathMatch && !input.force) {
    return {
      pathKeys: [],
      note: '仍在等待用户确认 path · 禁止自动评测（请 settleUserPathMatches 或 skipPendingPathMatchToSupervise）',
      raw: '',
    }
  }

  const docId = useIndexGate.getState().bookIndex?.docId?.trim() ?? ''
  if (!docId) {
    return { pathKeys: [], note: '信效度评测跳过 · 无 BookIndex/docId', raw: '' }
  }

  const inferEdges = st.inferEdges.filter((e) => e.queryKey === qk)
  const family = new Set(st.listQuerySelfAndAncestors(qk))
  const prospects = st.prospects.filter((p) => family.has(p.queryKey))
  let bound = bindInferProspectByBookLineage({
    docId,
    inferEdges,
    prospects,
    deskDeliveries: st.deskDeliveries,
  })
  // 若跳过时带了挂起绑定集，与现场绑定取交集（只评已展示给人手的同窝对）
  if (input.preBoundPairs && input.preBoundPairs.length > 0) {
    const allow = new Set(
      input.preBoundPairs.map((p) => `${p.inferKey}::${p.prospectKey}`),
    )
    bound = bound.filter((b) => allow.has(`${b.inferKey}::${b.prospectKey}`))
    if (bound.length === 0) {
      // 现场绑空但挂起有对：用挂起对 + 现账正文回填
      const byIk = new Map(inferEdges.map((e) => [e.inferKey, e]))
      const byPk = new Map(prospects.map((p) => [p.prospectKey, p]))
      bound = input.preBoundPairs
        .map((p) => {
          const e = byIk.get(p.inferKey)
          const pr = byPk.get(p.prospectKey)
          if (!e || !pr) return null
          return {
            inferKey: p.inferKey,
            prospectKey: p.prospectKey,
            briefKey: p.briefKey || pr.briefKey,
            sharedBookKeys: p.sharedBookKeys,
            inferText: (e.infer || e.rationale || '').trim(),
            prospectText: pr.text.trim(),
          }
        })
        .filter((x): x is NonNullable<typeof x> => Boolean(x))
    }
  }
  if (bound.length === 0) {
    return {
      pathKeys: [],
      note: `信效度评测跳过 · 无 book 同窝对 · ι×${inferEdges.length} · prospect×${prospects.length}`,
      raw: '',
    }
  }

  const allowed = new Set(
    bound.map((b) => `${b.inferKey}::${b.prospectKey}`),
  )
  const lines: string[] = [
    `queryKey=\`${qk}\``,
    `Q：${st.settledQueries[qk] ?? ''}`,
    '',
    '【台已按 book 血缘绑定的同窝对】（prospect→brief→book ∩ infer.bookKeys）',
    '你只评每对：这段推理是否印证该预测。禁止增删键对、禁止无血缘配对。',
    '输出要短：每行只要三字段，不要复述 ι/prospect 长文。',
    '',
  ]
  for (const b of bound) {
    lines.push(
      `──\ninferKey=\`${b.inferKey}\`\n` +
        `prospectKey=\`${b.prospectKey}\` · briefKey=\`${b.briefKey}\`\n` +
        `sharedBook=\`${b.sharedBookKeys.join(',')}\`\n` +
        `ι：${b.inferText.slice(0, 400)}\nprospect：${b.prospectText.slice(0, 400)}\n`,
    )
  }
  lines.push(
    '\n只输出一个 JSON 对象（可 ```json 围栏），不要散文：\n' +
      '{\n' +
      '  "judgments": [\n' +
      '    { "inferKey": "ik_…", "prospectKey": "pk_…", "status": "sufficient|insufficient" }\n' +
      '  ]\n' +
      '}\n' +
      '须覆盖上方每一对；sufficient=印证成立可铸 path；insufficient=同窝未兑现。' +
      '字段名必须是 inferKey / prospectKey / status。',
  )

  input.onProgress?.('写信台 · 同窝信效度评测（台已绑定）…')
  const chat = await flashChat({
    system: [
      '你是 path 信效度评审：键对已由写信台按材料血缘绑定。',
      '只判断 infer 是否印证 prospect 对 Q 的预测；不配对、不发明新键对。',
      '只输出合法 JSON（judgments 数组）；thinking 关闭场景下务必完整闭合括号。',
    ].join('\n'),
    user: lines.join('\n'),
    temperature: 0.1,
    maxTokens: 8192,
    retryOnEmpty: true,
  })
  if (!chat.ok) {
    return { pathKeys: [], note: `信效度评测失败：${chat.note}`, raw: '' }
  }

  ingestKeyIncrementStatuses({
    job: 'supervise',
    llmText: chat.content,
    windowKeys: [
      ...inferEdges.map((e) => e.inferKey),
      ...prospects.map((p) => p.prospectKey),
    ],
  })

  const judgments = parsePathValidityJudgments(chat.content)
  const clean = judgments.filter(
    (m) =>
      allowed.has(`${m.inferKey}::${m.prospectKey}`) &&
      m.status === 'sufficient',
  )
  if (clean.length === 0) {
    return {
      pathKeys: [],
      note: `信效度评测 · 同窝对×${bound.length} · 无 sufficient 可铸 path`,
      raw: chat.content,
    }
  }

  useAttentionIo.getState().clearPendingPathMatch()
  const settled = useAttentionIo.getState().settlePaths({
    queryKey: qk,
    llmCallId: newLlmCallId('path'),
    matches: clean.map((m) => ({
      inferKey: m.inferKey,
      prospectKey: m.prospectKey,
      matchMode: 'supervise_llm' as const,
    })),
  })
  return {
    pathKeys: settled.pathKeys,
    note: `信效度评测 · 同窝×${bound.length} · 印证 path×${settled.pathKeys.length}`,
    raw: chat.content,
  }
}

